methods.example:
part('Cone').loft([
  { on: 'front', draw: (s) => s.circle(10) },
  { on: at('front', 30), point: [0, 0] },
], { ends: { last: 'point' } });

part('Pipe').sweep(
  { on: 'front', draw: (s) => { s.circle(5); s.circle(4); } },
  { on: 'right', draw: (s) => s.polyline([[0, 0], [0, 40], [20, 60]]) },
);

part('Plate').sketch('front', (s) => s.rect(60, 40)).extrude(12)
  .hole(face('>Z'), [-15, 0], { diameter: 8 })
  .hole(face('>Z'), [15, 0], { kind: 'cbore', diameter: 6.6, cboreDiameter: 11, cboreDepth: 6 });

part('Tapped block').sketch('front', (s) => s.rect(30, 30)).extrude(20)
  .hole(face('>Z'), [0, 0], { diameter: 5, depth: 12 })
  .thread('hole', { size: 'M6', length: 10 });

part('Slots').sketch('front', (s) => s.rect(80, 30)).extrude(10)
  .sketch(face('>Z'), (s) => s.circle(3, [-30, 0])).cut(through())
  .linearPattern({ count: 4, spacing: 20, axis: 'x' });
